from collections import deque, defaultdict

def magnificent_sets(n, edges):
    # Build adjacency list (1-based)
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [0] * (n + 1)  # 0: unvisited, >0: group id
    answer = 0

    for node in range(1, n + 1):
        if visited[node]:
            continue

        # Find all nodes in this component
        component = []
        queue = deque([node])
        visited[node] = 1
        while queue:
            u = queue.popleft()
            component.append(u)
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = 1
                    queue.append(v)

        # For this component, check possible and find max level
        max_group = 0
        # Try each node as a starting point; find the largest possible group count
        for start in component:
            level = {start: 1}
            queue = deque([start])
            ok = True
            while queue and ok:
                u = queue.popleft()
                for v in graph[u]:
                    if v not in level:
                        level[v] = level[u] + 1
                        queue.append(v)
                    else:
                        if abs(level[v] - level[u]) != 1:
                            ok = False
                            break
            if ok:
                max_group = max(max_group, max(level.values()))
            else:
                return -1

        answer += max_group

    return answer
